11	    const child = spawn("npx", ["tsx", CLI_PATH], { stdio: ["pipe", "pipe", "pipe"] });
12	    let stdout = "";
13	    let stderr = "";
14	    child.stdout.on("data", (chunk) => (stdout += chunk));
15	    child.stderr.on("data", (chunk) => (stderr += chunk));
16	    child.on("error", reject);
17	    child.on("close", (code) => resolve({ stdout, stderr, exitCode: code ?? 0 }));
18	    child.stdin.end(input);
19	  });
