3	const readStdin = async (): Promise<string> => {
4	  const chunks: Buffer[] = [];
5	  for await (const chunk of process.stdin) chunks.push(Buffer.from(chunk));
6	  return Buffer.concat(chunks).toString("utf8");
7	};
8	
9	const input = await readStdin();
10	
11	try {
12	  const scenario = JSON.parse(input) as Scenario;
13	  process.stdout.write(JSON.stringify(runScenario(scenario)));
14	} catch (error) {
15	  process.stderr.write((error as Error).message);
16	  process.exit(1);
